import 'package:flutter/material.dart';import 'package:modulos/core/theme/app_colors.dart';import 'package:modulos/core/widgets/responsive_layout.dart';import '../controllers/configuracion_controller.dart';import '../widgets/configuracion_form.dart';import '../widgets/configuracion_table.dart';import '../widgets/configuracion_actions.dart';class ConfiguracionScreen extends StatefulWidget {  final int selectedNav;  final ValueChanged<int> onNavSelect;  const ConfiguracionScreen({super.key, required this.selectedNav, required this.onNavSelect});  @override  State<ConfiguracionScreen> createState() => _ConfiguracionScreenState();}class _ConfiguracionScreenState extends State<ConfiguracionScreen> {  final _controller = ConfiguracionController();  @override  void initState() {    super.initState();    _controller.addListener(() => setState(() {}));    _controller.cargarConfiguraciones();  }  @override  void dispose() {    _controller.dispose();    super.dispose();  }  void _abrirFormulario({dynamic existente}) {    showModalBottomSheet(      context: context,      isScrollControlled: true,      backgroundColor: AppColors.cardBg,      shape: const RoundedRectangleBorder(        borderRadius: BorderRadius.vertical(top: Radius.circular(20)),      ),      builder: (_) => ConfiguracionForm(        existente: existente,        onSubmit: (configuracion) async {          if (existente != null) {            await _controller.actualizarConfiguracion(configuracion);          } else {            await _controller.crearConfiguracion(configuracion);          }          if (mounted) {            ScaffoldMessenger.of(context).showSnackBar(              SnackBar(content: Text(existente != null ? 'Configuración actualizada' : 'Configuración creada')),            );          }        },      ),    );  }  @override  Widget build(BuildContext context) {    return ResponsiveLayout(      selectedNav: widget.selectedNav,      onNavSelect: widget.onNavSelect,      title: 'Configuración',      contentBuilder: (context, constraints) => _buildContent(),    );  }  Widget _buildContent() {    if (_controller.isLoading) {      return const Center(child: CircularProgressIndicator());    }    if (_controller.error != null) {      return Center(        child: Column(          mainAxisAlignment: MainAxisAlignment.center,          children: [            const Icon(Icons.error_outline, size: 48, color: AppColors.negativeRed),            const SizedBox(height: 16),            Text('Error: ${_controller.error}', style: const TextStyle(color: AppColors.textPrimary)),            const SizedBox(height: 16),            ElevatedButton(              onPressed: _controller.cargarConfiguraciones,              child: const Text('Reintentar'),              ),          ],        ),      );    }    return Column(      crossAxisAlignment: CrossAxisAlignment.start,      children: [        PageHeader(          title: 'Configuración del Sistema',          count: _controller.configuraciones.length,          buttonLabel: 'Nueva Configuración',          onButtonPressed: () => _abrirFormulario(),        ),        const SizedBox(height: 20),        if (_controller.configuraciones.isEmpty)          Container(            padding: const EdgeInsets.all(40),            decoration: BoxDecoration(              color: AppColors.cardBg,              borderRadius: BorderRadius.circular(16),              border: Border.all(color: AppColors.cardBorder),            ),            child: const Center(              child: Text('No hay configuraciones registradas', style: TextStyle(color: AppColors.textSecondary)),            ),          )        else          ConfiguracionTable(              configuraciones: _controller.configuraciones,              onEdit: (c) => _abrirFormulario(existente: c),              onDelete: (c) => ConfiguracionActions.confirmarEliminar(context, c, () async {                try {                  await _controller.eliminarConfiguracion(c.id);                  if (mounted) {                    ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content: Text('Configuración eliminada')));                  }                } catch (e) {                  if (mounted) {                    ScaffoldMessenger.of(context).showSnackBar(                      SnackBar(content: Text('Error: $e'), backgroundColor: AppColors.negativeRed),                    );                  }                }              }),            ),      ],    );  }}